#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* The lock covers the entire lifecycle and every read-modify-write operation.
 * Relaxed balance reads outside this lock would also be a data race. */
static void acquire(bank_account *account) {
#ifdef __cplusplus
    while (account->locked.exchange(true, std::memory_order_acquire)) {
    }
#else
    while (atomic_exchange_explicit(&account->locked, true, memory_order_acquire)) {
    }
#endif
}
static void release(bank_account *account) {
#ifdef __cplusplus
    account->locked.store(false, std::memory_order_release);
#else
    atomic_store_explicit(&account->locked, false, memory_order_release);
#endif
}
bool account_open(bank_account *account) {
    acquire(account);
    bool success = !account->is_open;
    if (success) {
        account->is_open = true;
        account->balance = 0;
    }
    release(account);
    return success;
}
bool account_close(bank_account *account) {
    acquire(account);
    bool success = account->is_open;
    if (success) {
        account->is_open = false;
        account->balance = 0;
    }
    release(account);
    return success;
}
bool account_balance(bank_account *account, int64_t *out) {
    acquire(account);
    bool success = account->is_open;
    if (success)
        *out = account->balance;
    release(account);
    return success;
}
bool account_deposit(bank_account *account, int64_t amount) {
    acquire(account);
    bool success =
        account->is_open && amount > 0 && account->balance <= INT64_MAX - amount;
    if (success)
        account->balance += amount;
    release(account);
    return success;
}
bool account_withdraw(bank_account *account, int64_t amount) {
    acquire(account);
    bool success = account->is_open && amount > 0 && amount <= account->balance;
    if (success)
        account->balance -= amount;
    release(account);
    return success;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
#include <threads.h>
#define WORKERS 8
#define ITERATIONS 20000
struct worker_data {
    bank_account *account;
    int phase;
    bool success;
};
static int transactions(void *data) {
    struct worker_data *worker = (struct worker_data *)data;
    worker->success = true;
    if (worker->phase == 2) {
        worker->success = account_open(worker->account);
        return 0;
    }
    if (worker->phase == 3) {
        worker->success = account_close(worker->account);
        return 0;
    }
    for (int i = 0; i < ITERATIONS; ++i) {
        bool ok = worker->phase == 0 ? account_deposit(worker->account, 1)
                                     : account_withdraw(worker->account, 1);
        if (!ok)
            worker->success = false;
    }
    return 0;
}
static unsigned parallel_phase(bank_account *account, int phase) {
    thrd_t threads[WORKERS];
    struct worker_data workers[WORKERS];
    for (int i = 0; i < WORKERS; ++i) {
        workers[i].account = account;
        workers[i].phase = phase;
        workers[i].success = false;
        assert(thrd_create(&threads[i], transactions, &workers[i]) == thrd_success);
    }
    unsigned successes = 0;
    for (int i = 0; i < WORKERS; ++i) {
        assert(thrd_join(threads[i], NULL) == thrd_success);
        successes += workers[i].success;
    }
    return successes;
}

int main(void) {

    bank_account a = {false, 0};
    int64_t b;
    assert(!account_balance(&a, &b) && !account_deposit(&a, 1));
    assert(account_open(&a) && !account_open(&a));
    assert(account_deposit(&a, 100) && account_withdraw(&a, 25));
    assert(account_balance(&a, &b) && b == 75);
    assert(!account_withdraw(&a, 76) && !account_deposit(&a, -1) &&
           !account_deposit(&a, 0) && !account_withdraw(&a, 0));
    assert(account_close(&a) && !account_close(&a));
    assert(account_open(&a) && account_balance(&a, &b) && b == 0);

    /* Contract: transactions and lifecycle changes are safe across threads. */
    bank_account shared = {false, 0};
    assert(parallel_phase(&shared, 2) == 1);
    assert(parallel_phase(&shared, 0) == WORKERS);
    assert(account_balance(&shared, &b) && b == WORKERS * ITERATIONS);
    assert(parallel_phase(&shared, 1) == WORKERS);
    assert(account_balance(&shared, &b) && b == 0);
    assert(parallel_phase(&shared, 3) == 1);
    assert(!account_deposit(&shared, 1) && !account_balance(&shared, &b));
    assert(account_open(&shared) && account_balance(&shared, &b) && b == 0);
    assert(account_close(&shared));

    return 0;
}
